package org.sebastiandev.trip.notification.grpc;
import com.google.protobuf.Timestamp; import io.grpc.Status; import io.quarkus.grpc.GrpcService; import io.smallrye.mutiny.Uni; import jakarta.inject.Inject; import java.util.UUID; import org.sebastiandev.trip.contracts.grpc.*; import org.sebastiandev.trip.notification.repository.NotificationRepository;
@GrpcService public class NotificationGrpcService implements NotificationQueryService{@Inject NotificationRepository notifications;@Override public Uni<GetNotificationResponse> getNotification(GetNotificationRequest request){try{return notifications.findById(UUID.fromString(request.getNotificationId())).onItem().ifNull().failWith(Status.NOT_FOUND.asRuntimeException()).invoke(n->{if(!request.getAdmin()&&!n.userId.toString().equals(request.getUserId()))throw Status.PERMISSION_DENIED.asRuntimeException();}).map(n->GetNotificationResponse.newBuilder().setNotification(NotificationView.newBuilder().setId(n.id.toString()).setUserId(n.userId.toString()).setType(n.type).setStatus(n.status).setPayloadJson(n.payloadJson).setCreatedAt(Timestamp.newBuilder().setSeconds(n.createdAt.toEpochSecond()).setNanos(n.createdAt.getNano()))).build());}catch(IllegalArgumentException e){return Uni.createFrom().failure(Status.INVALID_ARGUMENT.asRuntimeException());}}}
